h,w=23,21
g=[[4]*w for _ in range(h)]
seeds=[(14,11,5),(14,12,8),(15,11,9),(15,12,2),(16,10,9),(16,13,2)]
for r,c,v in seeds:g[r][c]=v
for color,points,dr,dc in [(9,[(15,11),(16,10)],1,-1),(2,[(15,12),(16,13)],1,1)]:
 for r,c in points:
  for sign in (-1,1):
   rr,cc=r+sign*dr,c+sign*dc
   while 0<=rr<h and 0<=cc<w and g[rr][cc]==4:
    g[rr][cc]=color; rr+=sign*dr; cc+=sign*dc
assert len(g)==23 and all(len(row)==21 for row in g) and all(g[r][c]==v for r,c,v in seeds)
print(__import__('json').dumps({'action':'submit','grid':g},separators=(',',':')))
